// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/core/ActionEncoder.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/PrecompileReader.sol";

// Mock CoreWriter to capture msg.sender and simulate HyperCore balance crediting
interface ICoreWriterMock {
    function sendRawAction(bytes calldata action) external;
}

contract MockCoreWriter {
    address public lastSender;
    mapping(address => uint256) public l1Balances;

    function sendRawAction(bytes calldata) external {
        lastSender = msg.sender;
        // HyperCore credits L1 balances to the msg.sender of sendRawAction
        l1Balances[msg.sender] += 1000; 
    }

    function getBalance(address account) external view returns (uint256) {
        return l1Balances[account];
    }
}

// Simulates MonetrixVault V1 where ActionEncoder is an inlined library.
// The internal function call means msg.sender to CoreWriter is the Vault itself.
contract VaultV1_Inlined {
    address public coreWriter;

    constructor(address _coreWriter) {
        coreWriter = _coreWriter;
    }

    function executeAction(bytes calldata data) external {
        // Inlined library logic: msg.sender here is VaultV1_Inlined
        ICoreWriterMock(coreWriter).sendRawAction(data);
    }
}

// Simulates the upgraded architecture where ActionEncoder is an external contract.
contract ExternalActionEncoder {
    address public coreWriter;

    constructor(address _coreWriter) {
        coreWriter = _coreWriter;
    }

    function executeAction(bytes calldata data) external {
        // External call: msg.sender here is ExternalActionEncoder, NOT the Vault!
        ICoreWriterMock(coreWriter).sendRawAction(data);
    }
}

// Simulates MonetrixVault V2 (post-upgrade) that delegates to the external encoder.
// Even if the Vault proxy address remains the same via UUPS, the call to CoreWriter
// originates from the ExternalActionEncoder contract.
contract VaultV2_External {
    ExternalActionEncoder public encoder;

    constructor(address _encoder) {
        encoder = ExternalActionEncoder(_encoder);
    }

    function executeAction(bytes calldata data) external {
        encoder.executeAction(data);
    }
}

contract ActionEncoderIdentityPoC is Test {
    MockCoreWriter coreWriter;
    VaultV1_Inlined vaultV1;
    VaultV2_External vaultV2;
    ExternalActionEncoder externalEncoder;

    function setUp() public {
        coreWriter = new MockCoreWriter();
        vaultV1 = new VaultV1_Inlined(address(coreWriter));
        externalEncoder = new ExternalActionEncoder(address(coreWriter));
        vaultV2 = new VaultV2_External(address(externalEncoder));
    }

    function test_identityAssumptionBreak() public {
        bytes memory dummyAction = hex"deadbeef";

        // Step 1: V1 uses inlined library logic. msg.sender to CoreWriter is the Vault.
        vaultV1.executeAction(dummyAction);
        address senderV1 = coreWriter.lastSender();
        uint256 balanceV1 = coreWriter.getBalance(address(vaultV1));

        console.log("V1 msg.sender:", senderV1);
        console.log("V1 L1 Balance:", balanceV1);
        assertEq(senderV1, address(vaultV1), "V1: msg.sender should be the Vault");
        assertGt(balanceV1, 0, "V1: Vault should have L1 balance");

        // Step 2: Upgrade to V2 which uses an external contract for ActionEncoder.
        // The proxy address might stay the same in a real UUPS, but the call to CoreWriter
        // now originates from the ExternalActionEncoder contract, not the Vault proxy.
        vaultV2.executeAction(dummyAction);
        address senderV2 = coreWriter.lastSender();
        uint256 balanceV2Proxy = coreWriter.getBalance(address(vaultV2));
        uint256 balanceV2Encoder = coreWriter.getBalance(address(externalEncoder));

        console.log("V2 msg.sender:", senderV2);
        console.log("V2 Proxy L1 Balance:", balanceV2Proxy);
        console.log("V2 Encoder L1 Balance:", balanceV2Encoder);

        // Step 3: Assert that the identity has changed, breaking the assumption that
        // "Vault's identity is the sole L1 account on HyperCore".
        assertNotEq(senderV2, address(vaultV2), "V2: msg.sender changed to external contract, breaking identity assumption!");

        // Step 4: Assert that L1 balances are stranded. The Vault proxy reads 0 balance,
        // which would cause totalBackingSigned() to return a drastically lower value,
        // triggering a false insolvency signal.
        assertEq(balanceV2Proxy, 0, "V2: Vault proxy has 0 balance (stranded funds)");
        assertGt(balanceV2Encoder, 0, "V2: External encoder holds the balance instead");
    }
}
